'use strict';
// CPSC 201 Pizza Shop Enterprise — all data and supplier messages are browser-local.
const DEPTS=[
 {name:'Sales & Marketing',icon:'🛒',roles:['Sales Specialist','Sales Manager','Sales Director'],systems:['CRM','MIS','ESS'],groups:[
 ['Record customer orders','Provide information about promotions','Handle customer inquiries'],['Review sales performance','Analyze customer feedback','Monitor promotional campaigns'],['Decide to open another location','Plan a new marketing strategy']]},
 {name:'Operations & Production',icon:'🍳',roles:['Chef','Operations Manager','Operations Director'],systems:['TPS','MIS','DSS'],groups:[
 ['Prepare customer pizzas','Check ingredient availability','Maintain kitchen cleanliness'],['Monitor preparation times','Identify bottlenecks','Improve delivery performance'],['Evaluate production capacity for new location','Plan future delivery areas']]},
 {name:'Finance & Accounting',icon:'💳',roles:['Cashier','Finance Manager','Finance Director'],systems:['TPS','MIS','ESS'],groups:[
 ['Process customer payments','Record daily cash transactions','Prepare end-of-day cash summary'],['Review sales and expenses','Control costs','Monitor profit and losses'],['Evaluate profitability','Decide on major investment']]},
 {name:'Human Resources',icon:'👥',roles:['HR Specialist','HR Manager','HR Director'],systems:['OSS','MIS','ESS'],groups:[
 ['Record employee attendance','Assign daily tasks','Provide on-the-job training'],['Review employee schedules','Monitor attendance','Identify training needs'],['Plan workforce needs for business growth','Develop long-term training plan']]},
 {name:'Supply Chain Management',icon:'🚚',roles:['Supply Chain Specialist','Supply Chain Manager','Supply Chain Director'],systems:['SCM','SCM','DSS'],groups:[
 ['Receive and check ingredient deliveries','Record inventory usage','Prepare purchase orders'],['Monitor inventory levels','Review supplier performance','Plan reordering and delivery schedules'],['Select new suppliers','Plan long-term supply strategy']]}];
const LEVELS=['Operational','Management','Executive'];
const PROCESSES=DEPTS.flatMap((d,di)=>d.groups.flatMap((g,li)=>g.map((name,pi)=>({id:`${di+1}-${li+1}-${pi+1}`,name,dept:d.name,deptIndex:di,level:LEVELS[li],levelIndex:li,role:d.roles[li],system:d.systems[li]}))));
const MENU=[{name:'Margherita',price:14,recipe:{Dough:1,Cheese:2,Tomato:2}},{name:'Pepperoni',price:17,recipe:{Dough:1,Cheese:2,Tomato:2,Pepperoni:2}},{name:'Veggie',price:16,recipe:{Dough:1,Cheese:2,Tomato:2,Vegetables:2}},{name:'Hawaiian',price:18,recipe:{Dough:1,Cheese:2,Tomato:2,Ham:2,Pineapple:2}}];
const SEED_STOCK={Dough:90,Cheese:180,Tomato:180,Pepperoni:95,Vegetables:95,Ham:75,Pineapple:75};
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+Number(n||0).toFixed(2), date=s=>new Date(s).toLocaleString(), uid=p=>`${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
let db, state, current=null, mode='employee';
const STORES=['orders','payments','inventory','purchases','employees','attendance','tasks','training','promotions','inquiries','feedback','expenses','cash','decisions','delivery','cleaning','suppliers','edi','audit','settings'];
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('cpsc201_pizza_enterprise_v3',1);r.onupgradeneeded=()=>{const d=r.result;for(const n of STORES)if(!d.objectStoreNames.contains(n))d.createObjectStore(n,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function all(store){return new Promise((res,rej)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function put(store,item){return new Promise((res,rej)=>{const r=db.transaction(store,'readwrite').objectStore(store).put(item);r.onsuccess=()=>res(item);r.onerror=()=>rej(r.error)})}
function atomic(changes){return new Promise((res,rej)=>{const stores=[...new Set(changes.map(c=>c[0]))];const tx=db.transaction(stores,'readwrite');changes.forEach(([s,x])=>tx.objectStore(s).put(x));tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error)})}
async function load(){state=Object.fromEntries(await Promise.all(STORES.map(async n=>[n,await all(n)])));}
const items=s=>state[s]||[], find=(s,id)=>items(s).find(x=>x.id===id), sum=(a,f)=>a.reduce((t,x)=>t+Number(f(x)||0),0), paid=()=>items('payments').filter(x=>x.kind==='order'), revenue=()=>sum(paid(),x=>x.amount), expenseTotal=()=>sum(items('expenses'),x=>x.amount)+sum(items('purchases').filter(x=>x.status==='Received'),x=>x.cost);
async function seed(){if(items('settings').length)return;const changes=[['settings',{id:'main',created:new Date().toISOString()}]];for(const [name,qty] of Object.entries(SEED_STOCK))changes.push(['inventory',{id:name,name,qty,reorder:25,unitCost:2,updated:new Date().toISOString()}]);for(const name of ['Maple Foods','West Coast Ingredients','Harvest Supply'])changes.push(['suppliers',{id:uid('SUP'),name,leadDays:name==='Maple Foods'?2:3,rating:4,status:'Active'}]);for(const name of ['Alex','Jordan','Taylor','Sam','Morgan','Casey'])changes.push(['employees',{id:uid('EMP'),name,role:'Staff',hourly:19,status:'Active'}]);changes.push(['promotions',{id:uid('PROM'),name:'Autumn Special',discount:10,status:'Active',reach:0,redemptions:0}]);await atomic(changes);await load()}
function alertMsg(msg,error=false){$('alert').innerHTML=`<div class="${error?'error':'success'}">${esc(msg)}</div>`;window.scrollTo({top:0,behavior:'smooth'})}
function metricHTML(){const orders=items('orders'),completed=orders.filter(x=>x.status==='Ready'||x.status==='Delivered').length;return [['Orders',orders.length],['Paid revenue',money(revenue())],['Kitchen completed',completed],['Low-stock ingredients',items('inventory').filter(x=>x.qty<=x.reorder).length]].map(([label,value])=>`<div class="metric"><small>${label}</small><strong>${value}</strong></div>`).join('')}
function setMetrics(){$('metrics').innerHTML=metricHTML()}
function navigation(){const selected=$('roleSelect').value;const role=DEPTS.flatMap(d=>d.roles.map((r,i)=>({r,d,i}))).find(x=>x.r===selected);$('navigation').innerHTML=DEPTS.map(d=>{const show=mode==='enterprise'||d===role?.d;if(!show)return '';return `<details class="dept" ${d===role?.d?'open':''}><summary>${d.icon} &nbsp;${esc(d.name)}</summary>${d.groups.map((g,i)=>{if(mode==='employee'&&i!==role?.i)return '';return `<div class="level">${LEVELS[i]} Level</div>${g.map(n=>{const p=PROCESSES.find(x=>x.name===n&&x.dept===d.name);return `<button class="process ${current?.id===p.id?'active':''}" data-id="${p.id}">${esc(n)}</button>`}).join('')}`}).join('')}</details>`}).join('');document.querySelectorAll('.process').forEach(b=>b.onclick=()=>showProcess(PROCESSES.find(p=>p.id===b.dataset.id)))}
function selectRole(){mode=$('viewMode').value;const r=$('roleSelect').value, permitted=PROCESSES.filter(p=>p.role===r);if(mode==='employee'&&current&&!permitted.some(p=>p.id===current.id))current=permitted[0];navigation();if(current)showProcess(current);else showHome()}
function table(store,cols,limit=12){const rows=items(store).slice(-limit).reverse();if(!rows.length)return '<p class="muted">No records yet. Complete a process to generate data.</p>';return `<div class="tablewrap"><table class="mini"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(typeof r[c]==='object'?JSON.stringify(r[c]):r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function showHome(){current=null;navigation();$('pageTitle').textContent='Enterprise Dashboard';$('pageSub').textContent='Integrated data across five business functions and three management levels';$('systemPill').textContent='TPS · CRM · MIS · DSS · ESS · OSS · SCM';setMetrics();const orderRows=items('orders').slice(-7).reverse();$('workspace').innerHTML=`<div class="grid"><section class="panel"><h2>Enterprise overview</h2><p>Choose a business function and one of its processes in the sidebar. Switch roles to see the employee's responsibilities.</p><div class="hint">40 business processes · 15 employee roles · 5 business functions. Employee View filters processes; Enterprise View shows the complete organizational model.</div><h3>Recent orders</h3>${orderRows.length?`<div class="tablewrap"><table class="mini"><tr><th>Order</th><th>Customer</th><th>Status</th><th>Amount</th></tr>${orderRows.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(o.customer)}</td><td>${esc(o.status)}</td><td>${money(o.total)}</td></tr>`).join('')}</table></div>`:'<p class="muted">No orders yet.</p>'}</section><section class="panel"><h2>Classroom controls</h2><p>Data is stored locally in IndexedDB in this browser profile. Other students do not share your records.</p><div class="actions"><button class="btn alt" id="exportBtn">Export JSON</button><label class="btn alt" for="importFile" style="cursor:pointer">Import JSON</label><input id="importFile" type="file" accept="application/json" hidden><button class="btn alt" id="resetBtn">Reset simulation</button></div><h3>Business performance</h3><p>Paid revenue: <b>${money(revenue())}</b></p><p>Recorded expenses and received supplies: <b>${money(expenseTotal())}</b></p><p>Simple cash-based margin (not full accrual accounting): <b>${money(revenue()-expenseTotal())}</b></p><h3>Process activity</h3>${table('audit',['process','role','timestamp'],5)}</section></div>`;bindHome()}
function bindHome(){$('exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify({app:'CPSC201-PizzaEnterprise',version:2,exported:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pizza-enterprise-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)};$('importFile').onchange=async e=>{try{const raw=JSON.parse(await e.target.files[0].text());if(raw.app!=='CPSC201-PizzaEnterprise'||raw.version!==2||!raw.data||!STORES.every(s=>Array.isArray(raw.data[s])))throw Error('Invalid or incompatible backup');if(!confirm('Import will overwrite matching records and may merge with existing data. Continue?'))return;for(const s of STORES)for(const r of raw.data[s])await put(s,r);await load();showHome();alertMsg('Backup imported.')}catch(e){alertMsg(e.message,true)}};$('resetBtn').onclick=async()=>{if(!confirm('Permanently erase ALL local simulation data in this browser?'))return;await new Promise((res,rej)=>{const tx=db.transaction(STORES,'readwrite');STORES.forEach(s=>tx.objectStore(s).clear());tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});await load();await seed();showHome();alertMsg('Simulation reset to initial inventory, suppliers and staff.')}}
// Form controls are defined per process, rather than static placeholders.
const field=(key,label,type='text',options=null,required=true)=>({key,label,type,options,required});
const F={text:(k,l)=>field(k,l),num:(k,l)=>field(k,l,'number'),opt:(k,l,o)=>field(k,l,'select',o),note:(k,l)=>field(k,l,'textarea'),date:(k,l)=>field(k,l,'date')};
function choices(store,labelKey='name',valueKey='id'){return items(store).map(x=>({value:x[valueKey],label:x[labelKey]}))}
function orderChoices(filter=()=>true){return items('orders').filter(filter).map(x=>({value:x.id,label:`${x.id} · ${x.customer} · ${x.status}`}))}
function formFor(p){const n=p.name;switch(n){
case 'Record customer orders':return [F.text('customer','Customer name'),F.opt('pizza','Pizza',MENU.map(x=>({value:x.name,label:`${x.name} · ${money(x.price)}`}))),F.num('qty','Quantity (1–20)'),F.opt('type','Fulfillment',['Pickup','Delivery']),F.text('address','Delivery address (required for delivery)')];
case 'Provide information about promotions':return [F.opt('promotion','Promotion',choices('promotions')),F.text('customer','Customer contacted'),F.opt('channel','Communication channel',['Phone','Email','In store'])];
case 'Handle customer inquiries':return [F.text('customer','Customer name'),F.opt('topic','Inquiry topic',['Menu','Order status','Allergens','Delivery','Other']),F.note('response','Response provided')];
case 'Review sales performance':return [F.opt('period','Reporting period',['All time','Today','Last 7 days']),F.note('finding','Manager interpretation')];
case 'Analyze customer feedback':return [F.text('customer','Customer name'),F.num('rating','Satisfaction rating (1–5)'),F.note('comment','Feedback and observation')];
case 'Monitor promotional campaigns':return [F.opt('promotion','Promotion',choices('promotions')),F.num('reach','New customers reached'),F.num('redemptions','New redemptions')];
case 'Decide to open another location':return [F.text('location','Proposed location'),F.num('startupCost','Estimated setup cost ($)'),F.num('monthlySales','Projected monthly sales ($)'),F.opt('decision','Decision',['Approve','Defer','Reject'])];
case 'Plan a new marketing strategy':return [F.text('strategy','Strategy name'),F.opt('segment','Target customers',['Families','Students','Office workers','All customers']),F.num('budget','Campaign budget ($)'),F.note('rationale','Strategic rationale')];
case 'Prepare customer pizzas':return [F.opt('orderId','Order to prepare',orderChoices(o=>o.status==='Submitted')),F.num('minutes','Actual preparation time (minutes)')];
case 'Check ingredient availability':return [F.opt('ingredient','Ingredient',choices('inventory')),F.num('needed','Quantity needed')];
case 'Maintain kitchen cleanliness':return [F.opt('station','Kitchen station',['Preparation bench','Oven','Refrigeration','Packing counter']),F.opt('result','Inspection result',['Clean','Needs attention']),F.note('notes','Inspection notes')];
case 'Monitor preparation times':return [F.num('target','Target preparation time (minutes)'),F.note('finding','Manager interpretation')];
case 'Identify bottlenecks':return [F.opt('station','Bottleneck area',['Preparation','Oven','Packing','Delivery']),F.note('cause','Observed cause'),F.note('action','Corrective action')];
case 'Improve delivery performance':return [F.opt('orderId','Delivery order',orderChoices(o=>o.type==='Delivery'&&o.status==='Ready')),F.num('minutes','Delivery duration (minutes)'),F.note('improvement','Improvement action')];
case 'Evaluate production capacity for new location':return [F.num('ovens','Proposed ovens'),F.num('pizzasPerHour','Pizzas per oven per hour'),F.num('demand','Expected orders per hour')];
case 'Plan future delivery areas':return [F.text('area','Proposed delivery area'),F.num('expectedOrders','Expected orders per day'),F.num('distance','Average delivery distance (km)'),F.opt('decision','Decision',['Expand','Pilot','Defer'])];
case 'Process customer payments':return [F.opt('orderId','Unpaid order',orderChoices(o=>!items('payments').some(x=>x.orderId===o.id))),F.opt('method','Payment method',['Cash','Card']),F.num('amount','Amount received ($)')];
case 'Record daily cash transactions':return [F.opt('kind','Transaction type',['Cash in','Cash out']),F.num('amount','Cash amount ($)'),F.text('description','Description')];
case 'Prepare end-of-day cash summary':return [F.date('day','Business date'),F.num('counted','Physical cash counted ($)')];
case 'Review sales and expenses':return [F.opt('period','Reporting period',['All time','Today','Last 7 days']),F.note('finding','Manager interpretation')];
case 'Control costs':return [F.opt('category','Expense category',['Utilities','Rent','Maintenance','Marketing','Wages','Other']),F.num('amount','Expense amount ($)'),F.text('description','Expense description')];
case 'Monitor profit and losses':return [F.opt('period','Reporting period',['All time','Today','Last 7 days']),F.note('action','Management response')];
case 'Evaluate profitability':return [F.num('target','Target cash margin (%)'),F.note('interpretation','Executive interpretation')];
case 'Decide on major investment':return [F.text('investment','Investment proposal'),F.num('cost','Upfront cost ($)'),F.num('annualBenefit','Expected annual benefit ($)'),F.opt('decision','Decision',['Approve','Defer','Reject'])];
case 'Record employee attendance':return [F.opt('employeeId','Employee',choices('employees')),F.opt('status','Attendance',['Present','Absent','Late']),F.num('hours','Hours worked')];
case 'Assign daily tasks':return [F.opt('employeeId','Employee',choices('employees')),F.text('task','Assigned task'),F.opt('priority','Priority',['Low','Medium','High'])];
case 'Provide on-the-job training':return [F.opt('employeeId','Employee',choices('employees')),F.text('topic','Training topic'),F.opt('result','Outcome',['Completed','Needs follow-up'])];
case 'Review employee schedules':return [F.opt('employeeId','Employee',choices('employees')),F.date('day','Shift date'),F.num('hours','Scheduled hours')];
case 'Monitor attendance':return [F.opt('employeeId','Employee',choices('employees')),F.note('followup','Manager follow-up')];
case 'Identify training needs':return [F.opt('employeeId','Employee',choices('employees')),F.text('skill','Skill gap'),F.opt('priority','Training priority',['Low','Medium','High'])];
case 'Plan workforce needs for business growth':return [F.num('expectedOrders','Projected daily orders'),F.num('ordersPerWorker','Orders handled per worker per day'),F.note('plan','Workforce plan')];
case 'Develop long-term training plan':return [F.text('program','Training program'),F.num('trainees','Target employee count'),F.num('budget','Training budget ($)'),F.note('objective','Learning objective')];
case 'Receive and check ingredient deliveries':return [F.opt('purchaseId','Outstanding purchase order',choices('purchases').filter(x=>x.status==='Ordered').map(x=>({value:x.id,label:`${x.id} · ${x.ingredient} × ${x.qty}`}))),F.num('received','Quantity received'),F.opt('quality','Quality inspection',['Accepted','Rejected'])];
case 'Record inventory usage':return [F.opt('ingredient','Ingredient',choices('inventory')),F.num('qty','Quantity used'),F.text('reason','Reason / reference')];
case 'Prepare purchase orders':return [F.opt('supplierId','Supplier',choices('suppliers')),F.opt('ingredient','Ingredient',choices('inventory')),F.num('qty','Order quantity'),F.num('unitCost','Price per unit ($)')];
case 'Monitor inventory levels':return [F.opt('ingredient','Ingredient',choices('inventory')),F.num('reorder','New reorder threshold')];
case 'Review supplier performance':return [F.opt('supplierId','Supplier',choices('suppliers')),F.num('rating','Supplier rating (1–5)'),F.note('notes','Performance notes')];
case 'Plan reordering and delivery schedules':return [F.opt('ingredient','Ingredient',choices('inventory')),F.num('target','Target stock quantity'),F.date('deliveryDate','Planned delivery date')];
case 'Select new suppliers':return [F.text('name','New supplier name'),F.num('leadDays','Lead time (days)'),F.num('rating','Evaluation rating (1–5)'),F.opt('decision','Selection decision',['Select','Shortlist','Reject'])];
case 'Plan long-term supply strategy':return [F.text('strategy','Supply strategy'),F.num('budget','Annual supply budget ($)'),F.note('risk','Supplier risk and mitigation')];
}return []}
function fieldHTML(f){let control='';if(f.type==='select'){const opts=(f.options||[]).map(x=>typeof x==='string'?{value:x,label:x}:x);control=`<select name="${f.key}" ${f.required?'required':''}><option value="">Choose...</option>${opts.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</select>`}else if(f.type==='textarea')control=`<textarea name="${f.key}" ${f.required?'required':''}></textarea>`;else control=`<input name="${f.key}" type="${f.type}" ${f.type==='number'?'step="any" min="0"':''} ${f.required?'required':''} ${f.key==='qty'?'value="1"':''}>`;return `<div class="field ${f.type==='textarea'?'wide':''}"><label for="f_${f.key}">${esc(f.label)}</label>${control}</div>`}
function relevantStore(p){return ['orders','promotions','inquiries','orders','feedback','promotions','decisions','decisions','orders','inventory','cleaning','orders','decisions','delivery','decisions','decisions','payments','cash','cash','expenses','expenses','expenses','decisions','decisions','attendance','tasks','training','tasks','attendance','training','decisions','training','purchases','inventory','purchases','inventory','suppliers','decisions','suppliers','decisions'][PROCESSES.indexOf(p)]}
function showProcess(p){current=p;navigation();$('pageTitle').textContent=p.name;$('pageSub').textContent=`${p.dept} · ${p.level} level · ${p.role}`;$('systemPill').textContent=p.system;setMetrics();const fs=formFor(p);const store=relevantStore(p);$('workspace').innerHTML=`<section class="panel"><h2>${esc(p.name)}</h2><p>Role: ${esc(p.role)} · Information system: ${esc(p.system)} · Process ${esc(p.id)}</p><form id="processForm"><div class="formgrid">${fs.map(fieldHTML).join('')}</div><div class="actions"><button class="btn" type="submit">Execute business process</button><button class="btn alt" type="button" id="refreshBtn">Refresh data</button></div></form></section><section class="panel"><h2>Process records</h2><div id="recordList">${recordTable(store)}</div></section>`;$('processForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{await execute(p,data);await load();showProcess(p);alertMsg(`Completed: ${p.name}. Saved to IndexedDB.`)}catch(err){alertMsg(err.message,true)}};$('refreshBtn').onclick=async()=>{await load();showProcess(p)}}
function recordTable(store){const rows=items(store).slice(-8).reverse();if(!rows.length)return '<p class="muted">No records available.</p>';return `<div class="tablewrap"><table class="mini"><tr><th>Record</th><th>Details</th><th>When</th></tr>${rows.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc([r.name,r.customer,r.ingredient,r.description,r.status,r.topic,r.strategy,r.decision,r.orderId].filter(Boolean).join(' · ').slice(0,100))}</td><td>${esc(r.timestamp?date(r.timestamp):r.createdAt?date(r.createdAt):'—')}</td></tr>`).join('')}</table></div>`}
function requireNum(v,label,min=0){const n=Number(v);if(v===''||!Number.isFinite(n)||n<min)throw Error(`${label} must be a number of at least ${min}.`);return n}
function requireText(v,label){if(!String(v||'').trim())throw Error(`${label} is required.`);return String(v).trim()}
function assertRating(v){const n=requireNum(v,'Rating',1);if(n>5)throw Error('Rating must be between 1 and 5.');return n}
function clone(x){return structuredClone(x)}
function decision(p,data,analysis){return {id:uid('DEC'),process:p.name,role:p.role,department:p.dept,inputs:data,analysis,timestamp:new Date().toISOString()}}
async function execute(p,d){const n=p.name,ts=new Date().toISOString(),changes=[],add=(s,x)=>changes.push([s,x]),newRecord=(s,props)=>add(s,{id:uid(s.toUpperCase().slice(0,3)),...props,timestamp:ts});let analysis='';
switch(n){
case 'Record customer orders':{const m=MENU.find(x=>x.name===d.pizza),qty=requireNum(d.qty,'Quantity',1);if(!Number.isInteger(qty)||qty>20)throw Error('Quantity must be a whole number between 1 and 20.');if(!m)throw Error('Choose a pizza.');if(d.type==='Delivery')requireText(d.address,'Delivery address');newRecord('orders',{customer:requireText(d.customer,'Customer name'),pizza:m.name,qty,unitPrice:m.price,total:m.price*qty,type:d.type,address:d.type==='Delivery'?d.address:'',status:'Submitted',prepMinutes:null,createdAt:ts});analysis=`Order created, ${qty} ${m.name}; kitchen queue updated. No payment recorded yet.`;break}
case 'Provide information about promotions':{const x=find('promotions',d.promotion);if(!x)throw Error('Choose a promotion.');newRecord('inquiries',{customer:requireText(d.customer,'Customer'),topic:'Promotion',response:`${x.name}: ${x.discount}% off`,channel:d.channel});analysis='Promotion information shared and customer contact logged.';break}
case 'Handle customer inquiries':newRecord('inquiries',{customer:requireText(d.customer,'Customer'),topic:d.topic,response:requireText(d.response,'Response')});analysis='Customer inquiry and response logged.';break;
case 'Review sales performance':{const a=filteredOrders(d.period);analysis=`${a.length} orders, ${money(sum(a,x=>x.total))} order value; ${money(sum(paid().filter(x=>a.some(o=>o.id===x.orderId)),x=>x.amount))} paid revenue.`;add('decisions',decision(p,d,analysis));break}
case 'Analyze customer feedback':{const rating=assertRating(d.rating);newRecord('feedback',{customer:requireText(d.customer,'Customer'),rating,comment:requireText(d.comment,'Feedback')});analysis=`Feedback rated ${rating}/5 recorded.`;break}
case 'Monitor promotional campaigns':{const x=find('promotions',d.promotion);if(!x)throw Error('Choose a promotion.');const reach=requireNum(d.reach,'Reach'),redemptions=requireNum(d.redemptions,'Redemptions');if(redemptions>reach)throw Error('Redemptions cannot exceed newly reached customers in this exercise.');add('promotions',{...x,reach:(x.reach||0)+reach,redemptions:(x.redemptions||0)+redemptions,updated:ts});analysis=`Campaign reach +${reach}; redemptions +${redemptions}.`;break}
case 'Decide to open another location':{const cost=requireNum(d.startupCost,'Startup cost',1),sales=requireNum(d.monthlySales,'Projected monthly sales');analysis=`Simple sales-to-startup ratio: ${(12*sales/cost).toFixed(2)} in year one (before expenses). Decision: ${d.decision}.`;add('decisions',decision(p,d,analysis));break}
case 'Plan a new marketing strategy':{requireText(d.strategy,'Strategy');const budget=requireNum(d.budget,'Budget');analysis=`${d.segment} target; proposed budget ${money(budget)}. Not spent until recorded in Finance.`;add('decisions',decision(p,d,analysis));break}
case 'Prepare customer pizzas':{const o=find('orders',d.orderId);if(!o||o.status!=='Submitted')throw Error('Choose a submitted order.');const minutes=requireNum(d.minutes,'Preparation time',1);const recipe=MENU.find(m=>m.name===o.pizza).recipe;for(const [name,per] of Object.entries(recipe)){const stock=find('inventory',name);if(!stock||stock.qty<per*o.qty)throw Error(`Insufficient ${name}: need ${per*o.qty}, available ${stock?.qty||0}.`)}for(const [name,per] of Object.entries(recipe)){const stock=find('inventory',name);add('inventory',{...stock,qty:stock.qty-per*o.qty,updated:ts})}add('orders',{...o,status:'Ready',prepMinutes:minutes,readyAt:ts});analysis=`Prepared ${o.qty} pizzas; ingredients consumed; order now Ready.`;break}
case 'Check ingredient availability':{const stock=find('inventory',d.ingredient);if(!stock)throw Error('Choose an ingredient.');const needed=requireNum(d.needed,'Needed quantity',1);analysis=`${stock.name}: available ${stock.qty}, needed ${needed}, ${stock.qty>=needed?'sufficient':'shortage of '+(needed-stock.qty)}.`;add('decisions',decision(p,d,analysis));break}
case 'Maintain kitchen cleanliness':newRecord('cleaning',{station:d.station,status:d.result,notes:d.notes});analysis='Kitchen inspection documented. Physical cleaning is not automated.';break;
case 'Monitor preparation times':{const a=items('orders').filter(o=>o.prepMinutes>0),avg=a.length?sum(a,o=>o.prepMinutes)/a.length:0,target=requireNum(d.target,'Target',1);analysis=`Average ${avg.toFixed(1)} min across ${a.length} prepared orders; target ${target} min.`;add('decisions',decision(p,d,analysis));break}
case 'Identify bottlenecks':analysis=`Observed ${d.station} bottleneck; cause: ${requireText(d.cause,'Cause')}; response: ${requireText(d.action,'Action')}.`;add('decisions',decision(p,d,analysis));break;
case 'Improve delivery performance':{const o=find('orders',d.orderId);if(!o||o.status!=='Ready'||o.type!=='Delivery')throw Error('Choose a ready delivery order.');const mins=requireNum(d.minutes,'Delivery duration',1);add('orders',{...o,status:'Delivered',deliveredAt:ts,deliveryMinutes:mins});newRecord('delivery',{orderId:o.id,minutes:mins,improvement:d.improvement});analysis=`Order delivered in ${mins} minutes.`;break}
case 'Evaluate production capacity for new location':{const ovens=requireNum(d.ovens,'Ovens',1),rate=requireNum(d.pizzasPerHour,'Production rate',1),demand=requireNum(d.demand,'Demand');analysis=`Estimated capacity ${ovens*rate} pizzas/hour; projected demand ${demand}/hour; ${ovens*rate>=demand?'capacity sufficient':'capacity shortfall '+(demand-ovens*rate)}.`;add('decisions',decision(p,d,analysis));break}
case 'Plan future delivery areas':{requireText(d.area,'Area');const orders=requireNum(d.expectedOrders,'Expected orders'),distance=requireNum(d.distance,'Distance');analysis=`Projected ${orders} orders/day over ${distance} km average; ${d.decision} decision recorded.`;add('decisions',decision(p,d,analysis));break}
case 'Process customer payments':{const o=find('orders',d.orderId);if(!o)throw Error('Choose an order.');if(items('payments').some(x=>x.orderId===o.id))throw Error('This order is already paid.');const amount=requireNum(d.amount,'Payment amount',0.01);if(Math.abs(amount-o.total)>.009)throw Error(`Payment must match the order total (${money(o.total)}).`);newRecord('payments',{orderId:o.id,kind:'order',method:d.method,amount});analysis=`Payment of ${money(amount)} recorded once; paid revenue increased.`;break}
case 'Record daily cash transactions':{const amount=requireNum(d.amount,'Amount',0.01);newRecord('cash',{kind:d.kind,amount,description:requireText(d.description,'Description')});analysis=`${d.kind} ${money(amount)} recorded in cash journal; not counted as order revenue.`;break}
case 'Prepare end-of-day cash summary':{const day=requireText(d.day,'Date'),counted=requireNum(d.counted,'Counted cash');const orderCash=sum(paid().filter(x=>x.method==='Cash'&&x.timestamp.startsWith(day)),x=>x.amount),journal=sum(items('cash').filter(x=>x.timestamp?.startsWith(day)),x=>x.kind==='Cash in'?x.amount:-x.amount);analysis=`Expected cash movement ${money(orderCash+journal)}; counted ${money(counted)}; difference ${money(counted-orderCash-journal)}. Opening float not modeled.`;newRecord('cash',{kind:'Summary',amount:counted,day,expected:orderCash+journal,difference:counted-orderCash-journal});break}
case 'Review sales and expenses':{const a=filteredOrders(d.period),pay=paid().filter(x=>a.some(o=>o.id===x.orderId));analysis=`Order value ${money(sum(a,x=>x.total))}; collected ${money(sum(pay,x=>x.amount))}; recorded all-time expenses/supplies ${money(expenseTotal())}.`;add('decisions',decision(p,d,analysis));break}
case 'Control costs':{const amount=requireNum(d.amount,'Expense',0.01);newRecord('expenses',{category:d.category,amount,description:requireText(d.description,'Description')});analysis=`Recorded ${money(amount)} ${d.category} expense.`;break}
case 'Monitor profit and losses':analysis=`Paid revenue ${money(revenue())} − recorded expenses/received supply cost ${money(expenseTotal())} = ${money(revenue()-expenseTotal())} cash-based proxy. Not an accounting P&L.`;add('decisions',decision(p,d,analysis));break;
case 'Evaluate profitability':{const target=requireNum(d.target,'Target margin');const margin=revenue()>0?100*(revenue()-expenseTotal())/revenue():0;analysis=`Simplified margin ${margin.toFixed(1)}% vs ${target}% target; excludes opening inventory, accruals and some labor costs.`;add('decisions',decision(p,d,analysis));break}
case 'Decide on major investment':{const cost=requireNum(d.cost,'Cost',1),benefit=requireNum(d.annualBenefit,'Benefit');analysis=`Simple payback ${benefit? (cost/benefit).toFixed(2)+' years':'not calculable'}; ${d.decision} decision recorded. No cash movement occurs.`;add('decisions',decision(p,d,analysis));break}
case 'Record employee attendance':{if(!find('employees',d.employeeId))throw Error('Choose an employee.');const hours=requireNum(d.hours,'Hours');if(hours>24)throw Error('Hours cannot exceed 24.');newRecord('attendance',{employeeId:d.employeeId,status:d.status,hours});analysis='Attendance recorded; hours can inform workforce analysis.';break}
case 'Assign daily tasks':{if(!find('employees',d.employeeId))throw Error('Choose an employee.');newRecord('tasks',{employeeId:d.employeeId,task:requireText(d.task,'Task'),priority:d.priority,status:'Assigned'});analysis='Task assigned to employee.';break}
case 'Provide on-the-job training':{if(!find('employees',d.employeeId))throw Error('Choose an employee.');newRecord('training',{employeeId:d.employeeId,topic:requireText(d.topic,'Topic'),result:d.result,type:'Delivered'});analysis='Training outcome recorded.';break}
case 'Review employee schedules':{if(!find('employees',d.employeeId))throw Error('Choose an employee.');const hours=requireNum(d.hours,'Scheduled hours');if(hours>24)throw Error('Hours cannot exceed 24.');newRecord('tasks',{employeeId:d.employeeId,task:`Scheduled shift ${d.day}`,hours,status:'Scheduled'});analysis='Shift scheduled and available in HR task records.';break}
case 'Monitor attendance':{if(!find('employees',d.employeeId))throw Error('Choose an employee.');const a=items('attendance').filter(x=>x.employeeId===d.employeeId);analysis=`Employee has ${a.length} attendance entries, ${a.filter(x=>x.status==='Absent').length} absences; follow-up: ${requireText(d.followup,'Follow-up')}.`;add('decisions',decision(p,d,analysis));break}
case 'Identify training needs':{if(!find('employees',d.employeeId))throw Error('Choose an employee.');newRecord('training',{employeeId:d.employeeId,topic:requireText(d.skill,'Skill gap'),result:'Needs training',priority:d.priority,type:'Needs assessment'});analysis='Training need added to HR records.';break}
case 'Plan workforce needs for business growth':{const orders=requireNum(d.expectedOrders,'Orders'),per=requireNum(d.ordersPerWorker,'Orders per worker',1);analysis=`Estimated workers required: ${Math.ceil(orders/per)} for ${orders} daily orders at ${per} per worker.`;add('decisions',decision(p,d,analysis));break}
case 'Develop long-term training plan':{const trainees=requireNum(d.trainees,'Trainees',1),budget=requireNum(d.budget,'Budget');analysis=`Plan for ${trainees} trainees with ${money(budget)} proposed budget; not recorded as expense.`;add('decisions',decision(p,d,analysis));break}
case 'Receive and check ingredient deliveries':{const po=find('purchases',d.purchaseId);if(!po||po.status!=='Ordered')throw Error('Choose an outstanding purchase order.');const qty=requireNum(d.received,'Received quantity',1);if(qty>po.qty)throw Error('Received quantity cannot exceed ordered quantity.');if(d.quality==='Rejected'){add('purchases',{...po,status:'Rejected',received:qty,receivedAt:ts});analysis='Delivery rejected; inventory unchanged.'}else{const stock=find('inventory',po.ingredient);add('inventory',{...stock,qty:stock.qty+qty,updated:ts});add('purchases',{...po,status:qty===po.qty?'Received':'Partially received',received:qty,cost:po.unitCost*qty,receivedAt:ts});analysis=`Accepted ${qty} ${po.ingredient}; stock increased. Supplier acknowledgment was simulated locally.`}break}
case 'Record inventory usage':{const stock=find('inventory',d.ingredient),qty=requireNum(d.qty,'Usage quantity',1);if(!stock||qty>stock.qty)throw Error('Insufficient inventory.');add('inventory',{...stock,qty:stock.qty-qty,updated:ts});newRecord('decisions',{process:p.name,role:p.role,department:p.dept,inputs:d,analysis:`Manual stock adjustment −${qty} ${stock.name}; ${requireText(d.reason,'Reason')}`,timestamp:ts});analysis='Inventory usage recorded and stock reduced.';break}
case 'Prepare purchase orders':{const sup=find('suppliers',d.supplierId),stock=find('inventory',d.ingredient),qty=requireNum(d.qty,'Quantity',1),unitCost=requireNum(d.unitCost,'Unit cost',0.01);if(!sup||!stock)throw Error('Choose supplier and ingredient.');const po={id:uid('PO'),supplierId:sup.id,ingredient:stock.name,qty,unitCost,cost:qty*unitCost,status:'Ordered',timestamp:ts};add('purchases',po);add('edi',{id:uid('EDI'),purchaseId:po.id,type:'PurchaseOrder',standard:'Educational EDI-style JSON',payload:{documentType:'PO',poNumber:po.id,supplier:sup.name,ingredient:stock.name,quantity:qty,unitCost},status:'Acknowledged (simulated)',timestamp:ts});analysis=`PO created for ${qty} ${stock.name}. EDI-style message and supplier acknowledgment simulated in this browser.`;break}
case 'Monitor inventory levels':{const stock=find('inventory',d.ingredient),threshold=requireNum(d.reorder,'Threshold');if(!stock)throw Error('Choose ingredient.');add('inventory',{...stock,reorder:threshold,updated:ts});analysis=`Reorder threshold set to ${threshold}; on-hand ${stock.qty}; ${stock.qty<=threshold?'reorder indicated':'stock above threshold'}.`;break}
case 'Review supplier performance':{const s=find('suppliers',d.supplierId);if(!s)throw Error('Choose supplier.');add('suppliers',{...s,rating:assertRating(d.rating),notes:d.notes,updated:ts});analysis='Supplier performance rating updated.';break}
case 'Plan reordering and delivery schedules':{const stock=find('inventory',d.ingredient),target=requireNum(d.target,'Target stock');if(!stock)throw Error('Choose ingredient.');analysis=`Plan to replenish ${Math.max(0,target-stock.qty)} units of ${stock.name} by ${d.deliveryDate}. No purchase order created until operational approval.`;add('decisions',decision(p,d,analysis));break}
case 'Select new suppliers':{const rating=assertRating(d.rating),days=requireNum(d.leadDays,'Lead time',1);newRecord('suppliers',{name:requireText(d.name,'Supplier name'),leadDays:days,rating,status:d.decision});analysis=`Supplier ${d.decision.toLowerCase()} with rating ${rating}/5 and ${days}-day lead time.`;break}
case 'Plan long-term supply strategy':{requireText(d.strategy,'Strategy');const budget=requireNum(d.budget,'Budget');analysis=`Annual proposed budget ${money(budget)}; risk: ${requireText(d.risk,'Risk mitigation')}.`;add('decisions',decision(p,d,analysis));break}
default:throw Error('Unsupported business process: '+n)
}
add('audit',{id:uid('AUD'),process:n,role:p.role,system:p.system,department:p.dept,analysis,timestamp:ts});await atomic(changes)}
function filteredOrders(period){const now=Date.now();return items('orders').filter(o=>period==='All time'||(period==='Today'&&new Date(o.createdAt).toDateString()===new Date().toDateString())||(period==='Last 7 days'&&now-new Date(o.createdAt).getTime()<7*86400000))}
async function init(){try{db=await openDB();await load();await seed();$('roleSelect').innerHTML=DEPTS.flatMap(d=>d.roles).map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('');$('roleSelect').value='Sales Specialist';$('roleSelect').onchange=selectRole;$('viewMode').onchange=selectRole;$('homeBtn').onclick=showHome;$('visualBtn').onclick=showVisualizations;$('analyticsBtn').onclick=showAnalytics;$('dssBtn').onclick=showDSS;$('essBtn').onclick=showESS;showHome()}catch(e){document.body.innerHTML=`<div style="padding:40px"><h1>Unable to start simulation</h1><p>${esc(e.message)}</p><p>Try Chrome with IndexedDB enabled. This application needs local browser storage.</p></div>`;console.error(e)}}
init();


// Professional decision-intelligence workspaces. Every chart is derived from IndexedDB state.
function studio(title,subtitle,system){current=null;navigation();$('pageTitle').textContent=title;$('pageSub').textContent=subtitle;$('systemPill').textContent=system;setMetrics()}
function chartSVG(points,type,labels=[],color='#2563eb'){const W=560,H=245,l=48,r=18,t=18,b=48;const w=W-l-r,h=H-t-b;const max=Math.max(1,...points.flatMap(p=>[Number(p.y)||0,Number(p.x)||0]));const ys=Math.max(1,...points.map(p=>Number(p.y)||0));const x=(i)=>l+(points.length<2?w/2:i*w/(points.length-1));const y=(v)=>t+h-(Math.max(0,v)/ys)*h;let g=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(type)} chart"><line x1="${l}" y1="${t+h}" x2="${W-r}" y2="${t+h}" stroke="#94a3b8"/><line x1="${l}" y1="${t}" x2="${l}" y2="${t+h}" stroke="#94a3b8"/>`;for(let k=0;k<=4;k++){const v=ys*k/4,yy=y(v);g+=`<line x1="${l}" y1="${yy}" x2="${W-r}" y2="${yy}" stroke="#e9eef5"/><text x="${l-8}" y="${yy+4}" text-anchor="end" fill="#64748b" font-size="10">${v.toFixed(v<10?1:0)}</text>`}if(type==='bar'||type==='hist'){const bw=w/Math.max(1,points.length),barw=Math.max(4,bw*.65);points.forEach((p,i)=>{const cx=l+bw*(i+.5);g+=`<rect x="${cx-barw/2}" y="${y(p.y)}" width="${barw}" height="${t+h-y(p.y)}" rx="3" fill="${color}"/><text x="${cx}" y="${H-22}" text-anchor="middle" fill="#64748b" font-size="10">${esc(String(p.label||'').slice(0,12))}</text>`})}else if(type==='line'){if(points.length>1)g+=`<polyline fill="none" stroke="${color}" stroke-width="3" points="${points.map((p,i)=>`${x(i)},${y(p.y)}`).join(' ')}"/>`;points.forEach((p,i)=>{g+=`<circle cx="${x(i)}" cy="${y(p.y)}" r="4" fill="${color}"/><text x="${x(i)}" y="${H-22}" text-anchor="middle" fill="#64748b" font-size="10">${esc(String(p.label||'').slice(0,10))}</text>`})}else if(type==='scatter'){const maxx=Math.max(1,...points.map(p=>p.x));points.forEach(p=>{const cx=l+(p.x/maxx)*w;g+=`<circle cx="${cx}" cy="${y(p.y)}" r="6" fill="${color}" fill-opacity=".65"><title>${esc(p.label||'')}: ${p.x} orders, ${p.y.toFixed(1)} min</title></circle>`});g+=`<text x="${W/2}" y="${H-8}" text-anchor="middle" font-size="11" fill="#64748b">Daily order volume</text>`}return g+'</svg>'}
function chartCard(title,description,svg,note=''){return `<section class="chart-card"><h3>${title}</h3><p>${description}</p>${svg}<div class="data-note">${note}</div></section>`}
function byDay(){const map=new Map();items('orders').forEach(o=>{const stamp=o.createdAt||o.timestamp;if(!stamp)return;const d=String(stamp).slice(0,10);if(!map.has(d))map.set(d,{day:d,orders:0,revenue:0,preps:[]});const x=map.get(d);x.orders++;if(Number(o.prepMinutes)>0)x.preps.push(Number(o.prepMinutes))});paid().forEach(p=>{const o=items('orders').find(x=>x.id===p.orderId);const d=String(p.timestamp||o?.createdAt||'').slice(0,10);if(map.has(d))map.get(d).revenue+=Number(p.amount)||0});return [...map.values()].sort((a,b)=>a.day.localeCompare(b.day))}
function showVisualizations(){studio('Visualization Studio','Five chart types from Week 4 · derived from simulation records','MIS · BI');const orders=items('orders'),daily=byDay();const bar=MENU.map(m=>({label:m.name,y:sum(orders.filter(o=>o.pizza===m.name),o=>o.qty)}));const line=daily.map(d=>({label:d.day.slice(5),y:d.revenue}));const prep=orders.map(o=>Number(o.prepMinutes)).filter(n=>Number.isFinite(n)&&n>0);const bins=[{label:'0–5',lo:0,hi:5},{label:'5–10',lo:5,hi:10},{label:'10–15',lo:10,hi:15},{label:'15–20',lo:15,hi:20},{label:'20+',lo:20,hi:Infinity}].map(z=>({label:z.label,y:prep.filter(n=>n>=z.lo&&n<z.hi).length}));const scatter=daily.filter(d=>d.preps.length).map(d=>({label:d.day,x:d.orders,y:sum(d.preps,x=>x)/d.preps.length}));const paidOrders=paid().length;const avgPrep=prep.length?sum(prep,x=>x)/prep.length:null;const kpis=`<div class="kpi-strip"><div>Paid revenue<strong>${money(revenue())}</strong></div><div>Recorded orders<strong>${orders.length}</strong></div><div>Average prep time<strong>${avgPrep===null?'No data':avgPrep.toFixed(1)+' min'}</strong></div></div>`;$('workspace').innerHTML=`<div class="chart-grid">${chartCard('1 · Bar chart','Pizza quantity by type',chartSVG(bar,'bar'),'Order quantities, including unpaid orders')}${chartCard('2 · Line chart','Daily paid revenue',daily.length?chartSVG(line,'line'):'<div class="empty-data">Create and pay orders to see a revenue trend.</div>','Revenue recognized from recorded payments')}${chartCard('3 · Histogram','Preparation time frequency',chartSVG(bins,'hist','#'),'Only orders with a recorded preparation time')}${chartCard('4 · Scatter plot','Daily order volume versus average preparation time',scatter.length?chartSVG(scatter,'scatter'):'<div class="empty-data">Complete kitchen preparation on orders to generate points.</div>','Each point represents one day with recorded preparation times')}${chartCard('5 · KPI dashboard','Summary of current operations',kpis,'Margin is not shown as accounting profit; data is browser-local')}</div>`}
function showAnalytics(){studio('Analytics Studio','Descriptive · Diagnostic · Predictive · Prescriptive','BI · Analytics');const daily=byDay(),orders=items('orders'),preps=orders.map(o=>Number(o.prepMinutes)).filter(x=>x>0),last7=daily.slice(-7),avg=last7.length?sum(last7,d=>d.orders)/last7.length:0;const delay=preps.filter(x=>x>12).length;const shortage=items('inventory').filter(i=>i.qty<=i.reorder);$('workspace').innerHTML=`<div class="chart-grid">${chartCard('Descriptive · What happened?','Historical orders, paid revenue, and preparation performance',`<div class="kpi-strip"><div>Orders<strong>${orders.length}</strong></div><div>Paid revenue<strong>${money(revenue())}</strong></div><div>Average prep<strong>${preps.length?(sum(preps,x=>x)/preps.length).toFixed(1)+' min':'—'}</strong></div></div>`,'Uses recorded business transactions')}${chartCard('Diagnostic · Why did it happen?','Investigate operational signals',`<p><b>${delay}</b> of ${preps.length} recorded preparation times exceeded the 12-minute reference threshold.</p><p><b>${shortage.length}</b> ingredients are at or below their reorder thresholds.</p><p>Inspect the kitchen, staffing, and supply-chain records to investigate causes.</p>`,'These are diagnostic clues, not proven causal explanations')}${chartCard('Predictive · What might happen?','Simple 7-observed-day moving-average forecast',`<div class="kpi-strip"><div>Expected next-day orders<strong>${last7.length?avg.toFixed(1):'—'}</strong></div><div>Observed days<strong>${last7.length}</strong></div><div>Forecast method<strong style="font-size:13px">Moving average</strong></div></div>`,'Educational statistical baseline; not a trained machine-learning model')}${chartCard('Prescriptive · What should we do?','Compare staffing choices under the same expected demand',`<div class="scenario-controls"><label>Expected orders<input id="presOrders" type="number" min="0" value="${Math.round(avg)||30}"></label><label>Orders per worker<input id="presRate" type="number" min="1" value="12"></label><label>Hourly cost ($)<input id="presWage" type="number" min="0" value="20"></label></div><div id="presOutput"></div>`,'Rule-based staffing comparison, not automated optimization')}</div>`;function update(){const n=Math.max(0,+$('presOrders').value||0),rate=Math.max(1,+$('presRate').value||1),wage=Math.max(0,+$('presWage').value||0),workers=Math.ceil(n/rate);$('presOutput').innerHTML=`<div class="scenario-results"><div>Suggested workers<strong>${workers}</strong></div><div>8-hour labor cost<strong>${money(workers*8*wage)}</strong></div><div>Capacity<strong>${workers*rate} orders</strong></div></div><p class="data-note">Assumes each worker can process ${rate} orders in the planning period; excludes skill mix and other constraints.</p>`}['presOrders','presRate','presWage'].forEach(id=>$(id).oninput=update);update()}
function showDSS(){studio('Decision Support System','Interactive what-if analysis · compare operational alternatives','DSS');const orders=items('orders');$('workspace').innerHTML=`<section class="panel"><div class="section-head"><h2>Capacity and staffing scenario planner</h2><span class="tag">What-if model</span></div><p>Change the assumptions to compare alternatives for a new location. These are illustrative planning estimates, not actual investment forecasts.</p><div class="scenario-controls"><label>Expected daily orders<input id="dOrders" type="number" min="0" value="60"></label><label>Orders per worker per day<input id="dRate" type="number" min="1" value="15"></label><label>Workers<input id="dWorkers" type="number" min="1" value="3"></label><label>Average order value ($)<input id="dValue" type="number" min="0" value="24"></label><label>Hourly wage ($)<input id="dWage" type="number" min="0" value="20"></label><label>Daily operating hours<input id="dHours" type="number" min="1" value="8"></label></div><div id="dssOutput"></div><div class="actions"><button class="btn" id="dssSave">Save decision scenario</button></div><p class="data-note">The model uses configurable assumptions; it does not automatically change employee schedules, inventory, or actual finances.</p></section><section class="panel"><h2>Related business processes</h2><p>Operations Director → Evaluate production capacity for new location; Finance Director → Decide on major investment; Supply Chain Director → Select new suppliers.</p><h3>Saved decisions</h3>${table('decisions',['process','analysis','timestamp'],6)}</section>`;function calc(){const n=+$('dOrders').value||0,r=Math.max(1,+$('dRate').value||1),w=+$('dWorkers').value||0,v=+$('dValue').value||0,hr=+$('dWage').value||0,h=+$('dHours').value||0;const capacity=r*w,served=Math.min(n,capacity),lost=Math.max(0,n-capacity),sales=served*v,labor=w*hr*h;$('dssOutput').innerHTML=`<div class="scenario-results"><div>Daily capacity<strong>${capacity} orders</strong></div><div>Unserved demand<strong>${lost} orders</strong></div><div>Potential daily sales<strong>${money(sales)}</strong></div><div>Daily labor cost<strong>${money(labor)}</strong></div><div>Sales less labor<strong>${money(sales-labor)}</strong></div><div>Capacity utilization<strong>${capacity?Math.round(served/capacity*100):0}%</strong></div></div><p class="data-note">Sales less labor is not profit; ingredients, rent, delivery and other costs are excluded.</p>`;return {capacity,lost,sales,labor}}['dOrders','dRate','dWorkers','dValue','dWage','dHours'].forEach(id=>$(id).oninput=calc);calc();$('dssSave').onclick=async()=>{const analysis=calc();await put('decisions',{id:uid('DSS'),process:'DSS capacity scenario',role:$('roleSelect').value,department:'Operations & Production',inputs:Object.fromEntries(['dOrders','dRate','dWorkers','dValue','dWage','dHours'].map(id=>[id,$(id).value])),analysis:JSON.stringify(analysis),timestamp:new Date().toISOString()});await load();showDSS();alertMsg('DSS scenario saved in IndexedDB.')}}
function showESS(){studio('Executive Support System','Strategic performance · business-wide KPIs · executive decisions','ESS');const orders=items('orders'),daily=byDay(),sales=daily.map(d=>({label:d.day.slice(5),y:d.revenue})),exp=expenseTotal(),rev=revenue(),cash=rev-exp;const decisions=items('decisions').slice(-8).reverse();$('workspace').innerHTML=`<section class="panel"><div class="section-head"><h2>Executive scorecard</h2><span class="tag">Strategic overview</span></div><div class="kpi-strip"><div>Paid revenue<strong>${money(rev)}</strong></div><div>Cash-based difference<strong>${money(cash)}</strong></div><div>Recorded orders<strong>${orders.length}</strong></div><div>Low-stock items<strong>${items('inventory').filter(i=>i.qty<=i.reorder).length}</strong></div><div>Recorded decisions<strong>${items('decisions').length}</strong></div><div>Completed orders<strong>${orders.filter(o=>['Ready','Delivered'].includes(o.status)).length}</strong></div></div><p class="data-note">Cash-based difference is revenue minus recorded expenses and received supply costs; it is not GAAP profitability.</p></section><div class="chart-grid">${chartCard('Revenue trend','Paid sales by day',daily.length?chartSVG(sales,'line'):'<div class="empty-data">Record paid orders to populate the trend.</div>')}${chartCard('Strategic decision register','Most recent executive and manager decisions',decisions.length?`<div class="tablewrap"><table class="mini"><tr><th>Process</th><th>Role</th><th>Recorded</th></tr>${decisions.map(d=>`<tr><td>${esc(d.process)}</td><td>${esc(d.role)}</td><td>${esc(String(d.timestamp||'').slice(0,10))}</td></tr>`).join('')}</table></div>`:'<div class="empty-data">No decisions recorded yet.</div>')}</div><section class="panel"><h2>Executive business processes</h2><p>Sales Director: new location and marketing strategy · Operations Director: capacity and delivery areas · Finance Director: profitability and investments · HR Director: workforce and training · Supply Chain Director: suppliers and long-term supply strategy.</p><div class="actions"><button class="btn" id="essExplore">Explore all executive processes</button><button class="btn alt" id="essDSS">Open DSS scenario planner</button></div></section>`;$('essExplore').onclick=()=>{$('viewMode').value='enterprise';mode='enterprise';navigation();alertMsg('Enterprise View enabled. Expand departments in the sidebar to select executive processes.')};$('essDSS').onclick=showDSS}
